why is this slower with more workers

```go
var mu sync.Mutex
var total int
func work(items []int, n int) int {
  var wg sync.WaitGroup
  ch := make(chan int)
  for i:=0;i<n;i++ { wg.Add(1); go func(){ defer wg.Done(); for x := range ch { mu.Lock(); total += expensive(x); mu.Unlock() } }() }
  for _, x := range items { ch <- x }
  close(ch); wg.Wait(); return total
}
```
1 worker 2s, 8 workers 5s
